   196→        message:    v.message,
   197→        severity:   v.severity,
   198→        repairHint: v.repairHint,
   199→      })),
   200→      summary:        report.summary,
   201→      satisfiedFacts: report.satisfiedFacts,
   202→      missingFacts:   report.missingFacts,
