   240→// ─── 엣지 포맷 정규화 ────────────────────────────────────────────
   241→// ai-generate: { from:"id", to:"id", fromPort, toPort }
   242→// Graph.fromJSON: { from:{nodeId,portId,portType}, to:{nodeId,portId,portType} }
   243→
   244→function normalizeGraph(graph) {
   245→  if (!graph) return graph;
   246→  const edges = (graph.edges || []).map((e, i) => {
   247→    const fromId = typeof e.from === 'string' ? e.from : (e.from?.nodeId ?? e.fn ?? '');
   248→    const toId   = typeof e.to   === 'string' ? e.to   : (e.to?.nodeId   ?? e.tn ?? '');
   249→    return {
   250→      id:   e.id ?? `e-${i}`,
   251→      from: { nodeId: fromId, portId: e.fromPort ?? e.fp ?? 0, portType: 'any' },
   252→      to:   { nodeId: toId,   portId: e.toPort   ?? e.tp ?? 0, portType: 'any' },
   253→    };
   254→  });
   255→  // nodes에 inputs/outputs 없으면 빈 배열 보장
   256→  const nodes = (graph.nodes || []).map(n => ({
   257→    inputs:  [],
   258→    outputs: [],
   259→    props:   {},
   260→    ...n,
   261→  }));
   262→  return { ...graph, nodes, edges };
   263→}
   264→
   265→// ─── 유틸 ────────────────────────────────────────────────────────
   266→
   267→function _generateNonce() {
   268→  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
   269→  let result = '';
   270→  for (let i = 0; i < 24; i++) result += chars[Math.floor(Math.random() * chars.length)];
   271→  return result;
   272→}
   273→
   274→function _escapeHtml(str) {
   275→  return String(str)
   276→    .replace(/&/g, '&amp;')
   277→    .replace(/</g, '&lt;')
   278→    .replace(/>/g, '&gt;')
   279→    .replace(/"/g, '&quot;')
   280→    .replace(/'/g, '&#39;');
   281→}
   282→
   283→function buildPreviewHtml({ html, css, js }, res) {
   284→  const nonce = _generateNonce();
   285→
   286→  // CSP 헤더: nonce를 가진 script만 허용, 외부 리소스 차단
   287→  if (res) {
   288→    res.setHeader(
   289→      'Content-Security-Policy',
   290→      `default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'; img-src data:;`
   291→    );
   292→  }
   293→
   294→  // html은 노드 그래프에서 생성된 마크업 — 태그 구조 유지, script/on* 속성만 제거
   295→  const safeHtml = (html || '<p style="color:#999">내용 없음</p>')
   296→    .replace(/<script[\s\S]*?<\/script>/gi, '')
   297→    .replace(/\s+on\w+="[^"]*"/gi, '')
   298→    .replace(/\s+on\w+='[^']*'/gi, '');
   299→
   300→  const safeCss = (css || '').replace(/<\/style>/gi, '');
   301→
   302→  return `<!DOCTYPE html>
   303→<html lang="ko">
   304→<head>
   305→  <meta charset="UTF-8">
   306→  <meta name="viewport" content="width=device-width, initial-scale=1.0">
   307→  <title>FreeWire 미리보기</title>
   308→  <style>
   309→    * { box-sizing: border-box; margin: 0; padding: 0; }
   310→    body { font-family: system-ui, sans-serif; padding: 24px; background: #f9fafb; }
   311→    .freewire-badge {
   312→      position: fixed; bottom: 12px; right: 12px;
   313→      background: #6366f1; color: white;
   314→      padding: 4px 10px; border-radius: 999px;
   315→      font-size: 12px; opacity: 0.85;
   316→    }
   317→    ${safeCss}
   318→  </style>
   319→</head>
   320→<body>
   321→  <div id="app">${safeHtml}</div>
   322→  <div class="freewire-badge">⚡ FreeWire</div>
   323→  <script nonce="${nonce}">${js || ''}</script>
   324→</body>
   325→</html>`;
   326→}
   327→
   328→function send(res, status, data) {
   329→  const body = JSON.stringify(data);
   330→  res.writeHead(status, {
   331→    'Content-Type':  'application/json',
   332→    'Access-Control-Allow-Origin': '*',
   333→    'Access-Control-Allow-Headers': 'Content-Type',
   334→  });
   335→  res.end(body);
   336→}
   337→
   338→const BODY_TIMEOUT_MS = 5_000;
   339→
   340→function readBody(req) {
   341→  return new Promise((resolve, reject) => {
   342→    let data = '', done = false;
   343→
   344→    const timer = setTimeout(() => {
   345→      if (!done) { done = true; req.destroy(); reject(new Error('요청 타임아웃 (5초 초과)')); }
   346→    }, BODY_TIMEOUT_MS);
   347→
   348→    const finish = (fn) => (...args) => {
   349→      if (done) return;
   350→      done = true;
   351→      clearTimeout(timer);
   352→      fn(...args);
   353→    };
   354→
   355→    req.on('data', chunk => {
   356→      data += chunk;
   357→      if (data.length > 1_000_000) {
   358→        done = true; clearTimeout(timer); req.destroy();
   359→        reject(new Error('너무 큰 요청'));
   360→      }
   361→    });
   362→    req.on('end',   finish(() => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } }));
   363→    req.on('error', finish(reject));
   364→  });
   365→}
   366→
   367→// ─── 서버 시작 ───────────────────────────────────────────────────
   368→const server = http.createServer((req, res) => {
   369→  if (req.method === 'OPTIONS') {
   370→    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'Content-Type', 'Access-Control-Allow-Methods': 'GET,POST' });
   371→    return res.end();
   372→  }
   373→  router(req, res);
   374→});
   375→
   376→if (require.main === module) {
   377→  server.listen(PORT, () => {
   378→    console.log(`\n⚡ FreeWire API 서버 시작`);
   379→    console.log(`   http://localhost:${PORT}/health`);
   380→    console.log(`   POST http://localhost:${PORT}/api/compile`);
   381→    console.log(`   POST http://localhost:${PORT}/api/execute`);
   382→    console.log(`   POST http://localhost:${PORT}/api/preview\n`);
   383→  });
   384→}
   385→
   386→module.exports = { server, previewCache };
   387→

