/**
 * FreeWire - 백엔드 API 서버
 * POST /compile  → 그래프 JSON → .free 코드
 * POST /execute  → 그래프 JSON → HTML/CSS/JS
 * GET  /preview/:id → 브라우저 미리보기
 * GET  /health
 */

const http = require('http');
const { Graph }          = require('../core/graph');
const { GraphCompiler }  = require('../compiler/graph-compiler');
const { FreeExecutor }   = require('./free-executor');
const { aiGenerateGraph } = require('./ai-graph-generator');
const { getBridge }      = require('../core/plugin-bridge');

const PORT = process.env.FREEWIRE_PORT || 4010;

const compiler = new GraphCompiler();
const executor = new FreeExecutor();

// 플러그인 시스템 초기화 (서버 시작 시 1회)
getBridge();

// 미리보기 캐시 { id → { html, css, js, createdAt } }
const previewCache = new Map();

// ─── 라우터 ─────────────────────────────────────────────────────
const ROUTES = {
  'GET /health':          handleHealth,
  'GET /api/nodes':       handleNodeTypes,
  'POST /api/compile':    handleCompile,
  'POST /api/execute':    handleExecute,
  'POST /api/preview':    handlePreviewCreate,
  'POST /api/ai-generate': handleAIGenerate,
  'POST /api/evaluate':   handleEvaluate,
  'POST /api/ir':         handleIR,
};

function router(req, res) {
  const key = `${req.method} ${req.url.split('?')[0]}`;

  // GET /preview/:id
  if (req.method === 'GET' && req.url.startsWith('/preview/')) {
    return handlePreviewGet(req, res);
  }

  const handler = ROUTES[key];
  if (handler) return handler(req, res);

  send(res, 404, { error: `라우트 없음: ${key}` });
}

// ─── 핸들러 ─────────────────────────────────────────────────────

function handleHealth(req, res) {
  send(res, 200, {
    status: 'ok',
    service: 'FreeWire API',
    version: '0.1.0',
    uptime: process.uptime().toFixed(1) + 's',
  });
}

function handleNodeTypes(req, res) {
  const { NODE_TYPE_DEFS } = require('../core/node-types-index');
  const nodeTypes = { ...NODE_TYPE_DEFS };

  // stdlib 카테고리 추가 (PluginBridge가 준비된 경우)
  const bridge = getBridge();
  const stdlibCategory = bridge.getPaletteCategory();
  if (stdlibCategory) {
    nodeTypes.stdlib = stdlibCategory;
  }

  send(res, 200, { nodeTypes });
}

async function handleCompile(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const result = compiler.compile(normalizeGraph(graph));
    send(res, 200, {
      code:     result.code,
      errors:   result.errors,
      warnings: result.warnings,
    });
  } catch (e) {
    send(res, 500, { error: '컴파일 실패: ' + e.message });
  }
}

async function handleExecute(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const ng = normalizeGraph(graph);
    const compiled = compiler.compile(ng);
    if (compiled.errors.length > 0) {
      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
    }
    const output = executor.execute(compiled.code, ng);
    send(res, 200, output);
  } catch (e) {
    send(res, 500, { error: '실행 실패: ' + e.message });
  }
}

async function handlePreviewCreate(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const ng = normalizeGraph(graph);
    const compiled = compiler.compile(ng);
    if (compiled.errors.length > 0) {
      return send(res, 422, { error: '컴파일 오류', details: compiled.errors });
    }
    const output = executor.execute(compiled.code, ng);
    const id     = `preview-${Date.now()}`;

    // 캐시 최대 100개 제한 (LRU: 가장 오래된 항목 제거)
    if (previewCache.size >= 100) {
      const oldest = previewCache.keys().next().value;
      previewCache.delete(oldest);
    }
    previewCache.set(id, { ...output, createdAt: Date.now() });

    // 캐시 1시간 TTL
    setTimeout(() => previewCache.delete(id), 3600_000);

    send(res, 201, { previewId: id, url: `/preview/${id}` });
  } catch (e) {
    send(res, 500, { error: '미리보기 생성 실패: ' + e.message });
  }
}


async function handleIR(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const result = compiler.compileToIR(normalizeGraph(graph));
    send(res, 200, { ir: result.ir, errors: result.errors, warnings: result.warnings });
  } catch (e) {
    send(res, 500, { error: 'IR 컴파일 실패: ' + e.message });
  }
}

async function handleEvaluate(req, res) {
  let body;
  try { body = await readBody(req); }
  catch (e) { return send(res, 400, { error: 'JSON 파싱 실패: ' + e.message }); }

  const { graph, goal } = body;
  if (!graph) return send(res, 400, { error: 'body.graph 필수' });

  try {
    const { IntentEvaluator } = require('../intent/evaluator');
    const nodesMap = new Map((graph.nodes || []).map(n => [n.id, n]));
    // 엣지 포맷 정규화: {from:"id"} 또는 {from:{nodeId}} 둘 다 지원
    const normalizedEdges = (graph.edges || []).map((e, i) => ({
      id:   e.id || `e-${i}`,
      fn:   typeof e.from === 'string' ? e.from : (e.from?.nodeId ?? e.fn),
      tn:   typeof e.to   === 'string' ? e.to   : (e.to?.nodeId   ?? e.tn),
      fp:   e.fromPort ?? e.fp ?? 0,
      tp:   e.toPort   ?? e.tp ?? 0,
    }));
    const wiresMap = new Map(normalizedEdges.map(e => [e.id, e]));
    const evaluator = new IntentEvaluator();
    const report = evaluator.evaluate(nodesMap, wiresMap, goal || '');
    send(res, 200, {
      score:      report.score,
      passed:     report.passed,
      violations: (report.violations || []).map(v => ({
        type:       v.type,
        message:    v.message,
        severity:   v.severity,
        repairHint: v.repairHint,
      })),
      summary:        report.summary,
      satisfiedFacts: report.satisfiedFacts,
      missingFacts:   report.missingFacts,
    });
  } catch (e) {
    send(res, 500, { error: '평가 실패: ' + e.message });
  }
}

