// ai-generate: { from:"id", to:"id", fromPort, toPort }
// Graph.fromJSON: { from:{nodeId,portId,portType}, to:{nodeId,portId,portType} }

function normalizeGraph(graph) {
  if (!graph) return graph;
  const edges = (graph.edges || []).map((e, i) => {
    const fromId = typeof e.from === 'string' ? e.from : (e.from?.nodeId ?? e.fn ?? '');
    const toId   = typeof e.to   === 'string' ? e.to   : (e.to?.nodeId   ?? e.tn ?? '');
    return {
      id:   e.id ?? `e-${i}`,
      from: { nodeId: fromId, portId: e.fromPort ?? e.fp ?? 0, portType: 'any' },
      to:   { nodeId: toId,   portId: e.toPort   ?? e.tp ?? 0, portType: 'any' },
    };
  });
  // nodes에 inputs/outputs 없으면 빈 배열 보장
  const nodes = (graph.nodes || []).map(n => ({
    inputs:  [],
    outputs: [],
    props:   {},
    ...n,
  }));
  return { ...graph, nodes, edges };
}

