function _generateNonce() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  for (let i = 0; i < 24; i++) result += chars[Math.floor(Math.random() * chars.length)];
  return result;
}

function _escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function buildPreviewHtml({ html, css, js }, res) {
  const nonce = _generateNonce();

  // CSP 헤더: nonce를 가진 script만 허용, 외부 리소스 차단
  if (res) {
    res.setHeader(
      'Content-Security-Policy',
      `default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'; img-src data:;`
    );
  }

  // html은 노드 그래프에서 생성된 마크업 — 태그 구조 유지, script/on* 속성만 제거
  const safeHtml = (html || '<p style="color:#999">내용 없음</p>')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/\s+on\w+="[^"]*"/gi, '')
    .replace(/\s+on\w+='[^']*'/gi, '');

  const safeCss = (css || '').replace(/<\/style>/gi, '');

  return `<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>FreeWire 미리보기</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: system-ui, sans-serif; padding: 24px; background: #f9fafb; }
    .freewire-badge {
      position: fixed; bottom: 12px; right: 12px;
      background: #6366f1; color: white;
      padding: 4px 10px; border-radius: 999px;
      font-size: 12px; opacity: 0.85;
    }
    ${safeCss}
  </style>
</head>
<body>
  <div id="app">${safeHtml}</div>
  <div class="freewire-badge">⚡ FreeWire</div>
  <script nonce="${nonce}">${js || ''}</script>
</body>
</html>`;
}

function send(res, status, data) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    'Content-Type':  'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Content-Type',
  });
  res.end(body);
}

const BODY_TIMEOUT_MS = 5_000;

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '', done = false;

    const timer = setTimeout(() => {
      if (!done) { done = true; req.destroy(); reject(new Error('요청 타임아웃 (5초 초과)')); }
    }, BODY_TIMEOUT_MS);

    const finish = (fn) => (...args) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      fn(...args);
    };

    req.on('data', chunk => {
      data += chunk;
      if (data.length > 1_000_000) {
        done = true; clearTimeout(timer); req.destroy();
        reject(new Error('너무 큰 요청'));
      }
    });
    req.on('end',   finish(() => { try { resolve(JSON.parse(data)); } catch (e) { reject(e); } }));
    req.on('error', finish(reject));
  });
}

